-- Swipeshop: complete database setup for a NEW Supabase project.
-- Generated by scripts/build-setup-sql.ts from supabase/migrations + supabase/seed.sql.
-- Paste all of this into Supabase > SQL Editor > New query, then press Run. Run it once.

-- ===== migrations/20261031000000_initial_schema.sql =====
-- Swipeshop initial schema.
-- Mirrors src/domain/types.ts. Change both together.
--
-- Catalog tables (categories, retailers, products) are readable by everyone
-- and written only by server-side jobs using the service role (Phase 4 feed
-- imports), which bypasses RLS. User tables (swipes, saved_items) are private
-- to their owner through row-level security.

-- ---------------------------------------------------------------------------
-- Catalog
-- ---------------------------------------------------------------------------

create table public.categories (
  id          text primary key
              check (id in ('furniture', 'clothing', 'bedding', 'collectibles', 'decor', 'footwear')),
  label       text not null,
  sort_order  integer not null default 0
);

create table public.retailers (
  id      text primary key,
  name    text not null,
  domain  text not null unique
);

create table public.products (
  id           text primary key,
  category_id  text not null references public.categories (id),
  retailer_id  text not null references public.retailers (id),
  title        text not null,
  brand        text not null,
  description  text not null default '',
  price_cents  integer not null check (price_cents >= 0),
  currency     char(3) not null default 'USD',
  image_urls   text[] not null default '{}',
  product_url  text not null,
  style_tags   text[] not null default '{}',
  material     text not null default '',
  color        text not null default '',
  created_at   timestamptz not null default now(),
  -- Feed bookkeeping (Phase 4): lets imports upsert and dedupe across retailers.
  external_id  text,
  is_active    boolean not null default true,
  updated_at   timestamptz not null default now(),
  unique (retailer_id, external_id)
);

create index products_category_active_idx on public.products (category_id) where is_active;
create index products_retailer_idx on public.products (retailer_id);
create index products_style_tags_idx on public.products using gin (style_tags);

-- ---------------------------------------------------------------------------
-- User data
-- ---------------------------------------------------------------------------

-- The swipe log: source of truth for taste. Append-only from the client
-- (plus deleting your own rows, which is how undo works).
create table public.swipes (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  product_id   text not null references public.products (id) on delete cascade,
  category_id  text not null references public.categories (id),
  direction    text not null check (direction in ('keep', 'skip')),
  swiped_at    timestamptz not null default now(),
  -- Client-generated id so the offline queue can replay safely (Phase 3).
  client_id    text,
  unique (user_id, client_id)
);

create index swipes_user_time_idx on public.swipes (user_id, swiped_at desc);

-- Products the user has kept.
create table public.saved_items (
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  product_id  text not null references public.products (id) on delete cascade,
  saved_at    timestamptz not null default now(),
  primary key (user_id, product_id)
);

-- ---------------------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------------------

alter table public.categories  enable row level security;
alter table public.retailers   enable row level security;
alter table public.products    enable row level security;
alter table public.swipes      enable row level security;
alter table public.saved_items enable row level security;

create policy "Catalog: anyone can read categories"
  on public.categories for select to anon, authenticated using (true);

create policy "Catalog: anyone can read retailers"
  on public.retailers for select to anon, authenticated using (true);

create policy "Catalog: anyone can read active products"
  on public.products for select to anon, authenticated using (is_active);

create policy "Swipes: read own"
  on public.swipes for select to authenticated using ((select auth.uid()) = user_id);
create policy "Swipes: insert own"
  on public.swipes for insert to authenticated with check ((select auth.uid()) = user_id);
create policy "Swipes: delete own"
  on public.swipes for delete to authenticated using ((select auth.uid()) = user_id);

create policy "Saved items: read own"
  on public.saved_items for select to authenticated using ((select auth.uid()) = user_id);
create policy "Saved items: insert own"
  on public.saved_items for insert to authenticated with check ((select auth.uid()) = user_id);
create policy "Saved items: delete own"
  on public.saved_items for delete to authenticated using ((select auth.uid()) = user_id);

-- ===== migrations/20261101000000_wishlists.sql =====
-- Named wishlists. Mirrors `Wishlist` / `WishlistItem` in src/domain/types.ts.

create table public.wishlists (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name        text not null check (char_length(btrim(name)) between 1 and 40),
  created_at  timestamptz not null default now()
);

-- One list per name per user, ignoring case (matches the app's rule).
create unique index wishlists_user_name_idx on public.wishlists (user_id, lower(name));

create table public.wishlist_items (
  wishlist_id  uuid not null references public.wishlists (id) on delete cascade,
  product_id   text not null references public.products (id) on delete cascade,
  added_at     timestamptz not null default now(),
  primary key (wishlist_id, product_id)
);

alter table public.wishlists      enable row level security;
alter table public.wishlist_items enable row level security;

create policy "Wishlists: read own"
  on public.wishlists for select to authenticated using ((select auth.uid()) = user_id);
create policy "Wishlists: insert own"
  on public.wishlists for insert to authenticated with check ((select auth.uid()) = user_id);
create policy "Wishlists: update own"
  on public.wishlists for update to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "Wishlists: delete own"
  on public.wishlists for delete to authenticated using ((select auth.uid()) = user_id);

-- Items are visible/editable only through a list you own.
create policy "Wishlist items: read own"
  on public.wishlist_items for select to authenticated
  using (exists (select 1 from public.wishlists w where w.id = wishlist_id and w.user_id = (select auth.uid())));
create policy "Wishlist items: insert own"
  on public.wishlist_items for insert to authenticated
  with check (exists (select 1 from public.wishlists w where w.id = wishlist_id and w.user_id = (select auth.uid())));
create policy "Wishlist items: delete own"
  on public.wishlist_items for delete to authenticated
  using (exists (select 1 from public.wishlists w where w.id = wishlist_id and w.user_id = (select auth.uid())));

-- ===== migrations/20261103000000_furniture_rooms.sql =====
-- MVP scope: furniture only, organised by room and product type.
-- Mirrors CATEGORY_IDS / SUBCATEGORY_IDS and Product.subcategoryId in
-- src/domain/types.ts. Safe to run now: there are no real users or products yet.

-- Rooms replace the old shopping categories.
alter table public.categories drop constraint categories_id_check;
alter table public.categories
  add constraint categories_id_check check (id in ('bedroom', 'living-room', 'kitchen-dining'));

-- Product types within a room (sofas, nightstands, bar stools...).
create table public.subcategories (
  id           text primary key
               check (id in ('bed-frames', 'nightstands', 'dressers', 'sofas', 'accent-chairs',
                             'coffee-tables', 'tv-stands', 'rugs', 'bar-stools', 'dining-tables',
                             'dining-chairs')),
  category_id  text not null references public.categories (id),
  label        text not null,
  sort_order   integer not null default 0
);

alter table public.subcategories enable row level security;
create policy "Catalog: anyone can read subcategories"
  on public.subcategories for select to anon, authenticated using (true);

-- Every product belongs to one product type. A trigger keeps the product's
-- room in step with its type so the two can never disagree.
alter table public.products add column subcategory_id text not null references public.subcategories (id);
create index products_subcategory_active_idx on public.products (subcategory_id) where is_active;

create function public.products_room_matches_type() returns trigger
language plpgsql as $$
begin
  select category_id into new.category_id from public.subcategories where id = new.subcategory_id;
  if new.category_id is null then
    raise exception 'Unknown product type: %', new.subcategory_id using errcode = 'foreign_key_violation';
  end if;
  return new;
end $$;

create trigger products_room_matches_type
  before insert or update of subcategory_id, category_id on public.products
  for each row execute function public.products_room_matches_type();

insert into public.categories (id, label, sort_order) values
  ('bedroom', 'Bedroom', 1),
  ('living-room', 'Living room', 2),
  ('kitchen-dining', 'Kitchen & dining', 3)
on conflict (id) do update set label = excluded.label, sort_order = excluded.sort_order;

insert into public.subcategories (id, category_id, label, sort_order) values
  ('bed-frames', 'bedroom', 'Bed frames', 1),
  ('nightstands', 'bedroom', 'Nightstands', 2),
  ('dressers', 'bedroom', 'Dressers', 3),
  ('sofas', 'living-room', 'Sofas', 1),
  ('accent-chairs', 'living-room', 'Accent chairs', 2),
  ('coffee-tables', 'living-room', 'Coffee tables', 3),
  ('tv-stands', 'living-room', 'TV stands', 4),
  ('rugs', 'living-room', 'Rugs', 5),
  ('bar-stools', 'kitchen-dining', 'Bar stools', 1),
  ('dining-tables', 'kitchen-dining', 'Dining tables', 2),
  ('dining-chairs', 'kitchen-dining', 'Dining chairs', 3);

-- ===== migrations/20261104000000_accounts_sync.sql =====
-- Phase 3: accounts and sync.

-- One row per signed-in user: things that aren't swipes but shape taste.
create table public.profiles (
  user_id      uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  style_picks  text[] not null default '{}',
  onboarded    boolean not null default false,
  updated_at   timestamptz not null default now()
);

alter table public.profiles enable row level security;
create policy "Profiles: read own"
  on public.profiles for select to authenticated using ((select auth.uid()) = user_id);
create policy "Profiles: insert own"
  on public.profiles for insert to authenticated with check ((select auth.uid()) = user_id);
create policy "Profiles: update own"
  on public.profiles for update to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

-- Every swipe now carries the id the phone gave it, so a swipe sent twice
-- (e.g. replayed from the offline queue) is stored once, and undo can delete it.
update public.swipes set client_id = id::text where client_id is null;
alter table public.swipes alter column client_id set not null;

-- Lists can be renamed on another device; let the owner update items too
-- (needed for upserts from the offline queue).
create policy "Wishlist items: update own"
  on public.wishlist_items for update to authenticated
  using (exists (select 1 from public.wishlists w where w.id = wishlist_id and w.user_id = (select auth.uid())))
  with check (exists (select 1 from public.wishlists w where w.id = wishlist_id and w.user_id = (select auth.uid())));

create policy "Saved items: update own"
  on public.saved_items for update to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

-- "Delete my account": required by the App Store. Removes the sign-in and,
-- through the cascades above, every swipe, kept item, list and profile.
create function public.delete_my_account()
returns void
language sql
security definer
set search_path = ''
as $$
  delete from auth.users where id = (select auth.uid());
$$;

revoke execute on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

-- ===== migrations/20261105000000_waitlist.sql =====
-- Website waitlist: anyone can add their email; nobody can read the list
-- through the public API (you read it in the Supabase dashboard).
create table public.waitlist (
  email       text primary key check (email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' and char_length(email) <= 254),
  source      text not null default 'website' check (char_length(source) <= 40),
  created_at  timestamptz not null default now()
);

alter table public.waitlist enable row level security;

create policy "Waitlist: anyone can join"
  on public.waitlist for insert to anon, authenticated with check (true);

-- Only inserting is allowed for the public: no select, update or delete.
revoke all on public.waitlist from anon, authenticated;
grant insert on public.waitlist to anon, authenticated;

-- ===== migrations/20261106000000_waitlist_signups.sql =====
-- Website waitlist v2: signups are written ONLY by the `waitlist-signup` Edge
-- Function (supabase/functions/waitlist-signup), which validates the email,
-- applies rate limits and records consent. The browser never talks to these
-- tables directly, and the public API roles (anon, authenticated) have no access.
--
-- This migration only ADDS objects. It does not change or drop anything that
-- already exists (the older `public.waitlist` table is left as it is).

-- 1. Signups -----------------------------------------------------------------
create table public.waitlist_signups (
  id                    uuid primary key default gen_random_uuid(),
  -- Stored already normalized (trimmed, lower case), see the check below.
  email                 text not null,
  -- Which form the person used: the hero form or the bottom-of-page form.
  source                text not null,
  -- Consent: exactly which disclosure the person saw next to the form, and when.
  consent_version       text not null,
  consent_text          text not null,
  consented_at          timestamptz not null default now(),
  -- Launch updates only. Nothing ever sets this to true today; it exists so a
  -- future, separate marketing opt-in can be recorded explicitly.
  marketing_opt_in      boolean not null default false,
  created_at            timestamptz not null default now(),
  -- Reserved for later email work (confirmation / welcome / unsubscribe).
  confirmed_at          timestamptz,
  welcome_email_sent_at timestamptz,
  unsubscribed_at       timestamptz,

  constraint waitlist_signups_email_normalized check (email = lower(btrim(email))),
  constraint waitlist_signups_email_format check (
    char_length(email) between 3 and 254 and email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  ),
  constraint waitlist_signups_source_check check (source in ('hero', 'footer')),
  constraint waitlist_signups_consent_version_check check (char_length(consent_version) between 1 and 40),
  constraint waitlist_signups_consent_text_check check (char_length(consent_text) between 1 and 500)
);

-- One row per email, ignoring upper/lower case.
create unique index waitlist_signups_email_key on public.waitlist_signups (lower(email));
create index waitlist_signups_created_at_idx on public.waitlist_signups (created_at desc);

comment on table public.waitlist_signups is
  'Website waitlist. Written only by the waitlist-signup Edge Function via public.waitlist_signup(). Launch updates only.';

-- 2. Rate limiting -----------------------------------------------------------
-- One row per signup attempt, keyed by a salted SHA-256 hash of the visitor's
-- IP address (the raw IP is never stored). Rows older than one day are deleted
-- automatically by public.waitlist_signup().
create table public.waitlist_rate_limits (
  id          bigint generated always as identity primary key,
  client_hash text not null check (client_hash ~ '^[0-9a-f]{64}$'),
  created_at  timestamptz not null default now()
);

create index waitlist_rate_limits_client_idx on public.waitlist_rate_limits (client_hash, created_at desc);
create index waitlist_rate_limits_created_at_idx on public.waitlist_rate_limits (created_at);

comment on table public.waitlist_rate_limits is
  'Short-lived signup attempt log (salted IP hashes) used to rate-limit the waitlist. Auto-pruned after 1 day.';

-- 3. Lock both tables down ---------------------------------------------------
-- Row Level Security on, with NO policies: the public API roles can never see
-- or change a row, even if a grant were added by mistake later.
alter table public.waitlist_signups enable row level security;
alter table public.waitlist_rate_limits enable row level security;

-- Supabase grants new public tables to the API roles by default; take that back.
-- (You still see and manage the list in the Supabase dashboard.)
revoke all on table public.waitlist_signups from public, anon, authenticated, service_role;
revoke all on table public.waitlist_rate_limits from public, anon, authenticated, service_role;

-- 4. The only way in ---------------------------------------------------------
-- Validates, rate-limits and inserts in one transaction. Returns one of:
--   'created'        new signup stored
--   'exists'         email already on the list (nothing changed)
--   'rate_limited'   too many attempts from this visitor
--   'invalid_email'  email failed validation
--   'invalid_request' unknown form source or consent details
create function public.waitlist_signup(
  p_email           text,
  p_source          text,
  p_consent_version text,
  p_consent_text    text,
  p_client_hash     text
)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email  text := lower(btrim(coalesce(p_email, '')));
  v_recent integer;
  v_daily  integer;
  v_id     uuid;
begin
  if p_client_hash is null or p_client_hash !~ '^[0-9a-f]{64}$' then
    return 'invalid_request';
  end if;

  if char_length(v_email) not between 3 and 254
     or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    return 'invalid_email';
  end if;

  if p_source is null or p_source not in ('hero', 'footer')
     or p_consent_version is null or char_length(p_consent_version) not between 1 and 40
     or p_consent_text is null or char_length(p_consent_text) not between 1 and 500 then
    return 'invalid_request';
  end if;

  -- Count this visitor's attempts one request at a time, so parallel requests
  -- can't slip past the limit.
  perform pg_advisory_xact_lock(hashtextextended('waitlist:' || p_client_hash, 0));

  select count(*) filter (where created_at > now() - interval '10 minutes'),
         count(*)
    into v_recent, v_daily
    from public.waitlist_rate_limits
   where client_hash = p_client_hash
     and created_at > now() - interval '1 day';

  if v_recent >= 5 or v_daily >= 20 then
    return 'rate_limited';
  end if;

  insert into public.waitlist_rate_limits (client_hash) values (p_client_hash);
  delete from public.waitlist_rate_limits where created_at < now() - interval '1 day';

  insert into public.waitlist_signups (email, source, consent_version, consent_text)
  values (v_email, p_source, p_consent_version, p_consent_text)
  on conflict ((lower(email))) do nothing
  returning id into v_id;

  if v_id is null then
    return 'exists';
  end if;
  return 'created';
end;
$$;

comment on function public.waitlist_signup(text, text, text, text, text) is
  'Waitlist entry point for the waitlist-signup Edge Function (service role only).';

-- Only the server-side role used by the Edge Function may call it.
revoke all on function public.waitlist_signup(text, text, text, text, text) from public, anon, authenticated;
grant execute on function public.waitlist_signup(text, text, text, text, text) to service_role;

-- ===== migrations/20261107000000_product_feeds.sql =====
-- Phase 4: product feed imports.
--
-- feed_sources: one row per brand feed to import (an affiliate network program).
-- import_runs:  one row per import attempt, with the report (imported / skipped and why).
--
-- Both are server-only: RLS on and no policies, so the app can't read or write them.
-- The import-feeds Edge Function uses the service role, which bypasses RLS.

create table public.feed_sources (
  id            text primary key,                       -- our retailer id, e.g. 'awin-88509'
  network       text not null check (network in ('awin')),
  advertiser_id text not null,                          -- Awin "merchant id" (mid)
  feed_id       text not null,                          -- Awin feed id ("fid" in Create-a-Feed)
  name          text not null,                          -- shown in the app as the store name
  domain        text not null,                          -- e.g. 'superarearugs.com'
  enabled       boolean not null default true,
  max_products  integer not null default 2000 check (max_products between 1 and 20000),
  created_at    timestamptz not null default now()
);

create table public.import_runs (
  id           uuid primary key default gen_random_uuid(),
  source_id    text not null references public.feed_sources (id) on delete cascade,
  started_at   timestamptz not null default now(),
  finished_at  timestamptz,
  status       text not null default 'running' check (status in ('running', 'ok', 'failed')),
  imported     integer,
  deactivated  integer,
  report       jsonb,
  error        text
);

create index import_runs_source_started_idx on public.import_runs (source_id, started_at desc);

alter table public.feed_sources enable row level security;
alter table public.import_runs  enable row level security;

-- Latest run per brand, in plain columns: open this in the Supabase Table Editor.
-- security_invoker keeps the tables' RLS in force, so only the service role and the
-- dashboard (which run as admin) can read it.
create view public.import_report with (security_invoker = true) as
  select distinct on (r.source_id)
    s.name                                   as store,
    r.status,
    r.imported,
    r.deactivated,
    (r.report ->> 'rows')::int               as feed_rows,
    r.report -> 'skipped'                    as skipped,
    r.report -> 'byType'                     as by_type,
    r.error,
    r.finished_at
  from public.import_runs r
  join public.feed_sources s on s.id = r.source_id
  order by r.source_id, r.started_at desc;

revoke all on public.feed_sources, public.import_runs, public.import_report from anon, authenticated;

